export function initPagination(){const e=document.querySelector(".media-gallery"),t=[...document.querySelectorAll(".media-pagination button.page")],n=[...document.querySelectorAll(".page")],i=[...document.querySelectorAll(".media-pagination button")];let o=document.querySelector("nav.main-nav").getBoundingClientRect().height;const c=o+40;let a=n[0].getBoundingClientRect().width,d=window.innerWidth;const l=t=>{const o=t*a+15*t;(()=>{for(let e of i)e.classList.remove("active")})(),i[t].classList.add("active"),e.style.transform=`translateX(-${o}px)`,(()=>{const e=n[0].getBoundingClientRect().top+window.scrollY-c;window.scrollTo({top:e,behavior:"smooth"})})()};window.addEventListener("resize",(()=>{if(window.innerWidth!==d){o=document.querySelector("nav.main-nav").getBoundingClientRect().height,a=n[0].getBoundingClientRect().width;document.querySelector(".media-pagination button.active").click()}d=window.innerWidth}));for(let e of t){const t=+e.dataset.index;e.addEventListener("click",(()=>l(t)))}}